// Register this route before a general express.json() parser when exact raw bytes are required.
app.post('/webhooks/provider', express.raw({ type: 'application/json', limit: '256kb' }), (req, res) => {
  const rawBody = req.body;
  const signature = req.get('X-Provider-Signature');
  if (!verifyProviderSignature(rawBody, signature, process.env.WEBHOOK_SECRET)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }
  // Persist provider event ID before performing an idempotent state transition.
  return res.sendStatus(204);
});
